package com.ptu.backend.common.security;

import java.io.IOException;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.ptu.backend.common.api.ApiErrorWriter;
import com.ptu.backend.config.AppProperties;

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * Applies Redis-backed rate limits to the public API: login attempts per IP, requests of
 * authenticated users per user id, requests of anonymous callers per IP.
 * Registered inside the Spring Security chain (right after the JWT authentication filter).
 */
public class RateLimitFilter extends OncePerRequestFilter {

	static final String LOGIN_PATH = "/api/auth/login";
	static final String API_PREFIX = "/api/";

	private final RateLimiter rateLimiter;
	private final AppProperties properties;
	private final ObjectMapper objectMapper;

	public RateLimitFilter(RateLimiter rateLimiter, AppProperties properties, ObjectMapper objectMapper) {
		this.rateLimiter = rateLimiter;
		this.properties = properties;
		this.objectMapper = objectMapper;
	}

	@Override
	protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
			throws ServletException, IOException {
		AppProperties.RateLimit limits = properties.rateLimit();
		String path = request.getRequestURI();
		if (limits == null || !limits.enabled() || !path.startsWith(API_PREFIX)) {
			filterChain.doFilter(request, response);
			return;
		}

		String scope;
		String identity;
		AppProperties.Limit limit;
		if (HttpMethod.POST.matches(request.getMethod()) && LOGIN_PATH.equals(path)) {
			scope = "login";
			identity = clientIp(request);
			limit = limits.login();
		}
		else if (currentPrincipal() instanceof UserPrincipal principal) {
			scope = "user";
			identity = principal.id().toString();
			limit = limits.authenticated();
		}
		else {
			scope = "ip";
			identity = clientIp(request);
			limit = limits.anonymous();
		}

		RateLimiter.RateLimitDecision decision = rateLimiter.acquire(scope, identity, limit);
		if (!decision.allowed()) {
			response.setHeader(HttpHeaders.RETRY_AFTER, Long.toString(decision.retryAfterSeconds()));
			ApiErrorWriter.write(objectMapper, request, response, HttpStatus.TOO_MANY_REQUESTS,
					"Слишком много запросов, попробуйте позже");
			return;
		}
		filterChain.doFilter(request, response);
	}

	@Override
	protected boolean shouldNotFilter(HttpServletRequest request) {
		String path = request.getRequestURI();
		return path.startsWith("/actuator/") || !path.startsWith(API_PREFIX);
	}

	private static Object currentPrincipal() {
		Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
		return authentication == null ? null : authentication.getPrincipal();
	}

	private static String clientIp(HttpServletRequest request) {
		String forwarded = request.getHeader("X-Forwarded-For");
		if (forwarded != null && !forwarded.isBlank()) {
			return forwarded.split(",")[0].trim();
		}
		return request.getRemoteAddr();
	}
}
package com.ptu.backend.common.security;

import java.time.Duration;

import com.ptu.backend.config.AppProperties;

import org.springframework.dao.DataAccessException;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

import lombok.extern.slf4j.Slf4j;

/**
 * Fixed-window rate limiter backed by Redis counters.
 * The window index is part of the key, so counters never need to be reset manually.
 */
@Slf4j
@Component
public class RateLimiter {

	private static final String KEY_PREFIX = "rate_limit:";

	private final StringRedisTemplate redis;

	public RateLimiter(StringRedisTemplate redis) {
		this.redis = redis;
	}

	public RateLimitDecision acquire(String scope, String identity, AppProperties.Limit limit) {
		long windowSeconds = Math.max(limit.window().toSeconds(), 1);
		long now = System.currentTimeMillis() / 1000;
		long windowIndex = now / windowSeconds;
		long secondsLeft = windowSeconds - (now % windowSeconds);
		String key = KEY_PREFIX + scope + ":" + identity + ":" + windowIndex;

		try {
			Long count = redis.opsForValue().increment(key);
			if (count != null && count == 1L) {
				redis.expire(key, Duration.ofSeconds(windowSeconds));
			}
			if (count == null) {
				return RateLimitDecision.permit();
			}
			return count <= limit.requests()
					? RateLimitDecision.permit()
					: RateLimitDecision.deny(secondsLeft);
		}
		catch (DataAccessException ex) {
			log.warn("Rate limiter is unavailable, allowing request: {}", ex.getMessage());
			return RateLimitDecision.permit();
		}
	}

	public record RateLimitDecision(boolean allowed, long retryAfterSeconds) {

		static RateLimitDecision permit() {
			return new RateLimitDecision(true, 0);
		}

		static RateLimitDecision deny(long retryAfterSeconds) {
			return new RateLimitDecision(false, retryAfterSeconds);
		}
	}
}

package com.ptu.backend.mail;

import java.time.Duration;

import com.ptu.backend.common.exception.ApiException;
import com.ptu.backend.config.AppProperties;

import org.springframework.mail.MailException;
import org.springframework.mail.SimpleMailMessage;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.stereotype.Service;

import lombok.extern.slf4j.Slf4j;

@Slf4j
@Service
public class SmtpMailService implements MailService {

	private final JavaMailSender mailSender;
	private final String from;

	public SmtpMailService(JavaMailSender mailSender, AppProperties properties) {
		this.mailSender = mailSender;
		this.from = properties.mailFrom();
	}

	@Override
	public void sendVerificationCode(String email, String fullName, String code, Duration ttl) {
		String text = """
				Здравствуйте, %s!

				Код подтверждения регистрации: %s
				Код действует %d минут и может быть использован только один раз.
				""".formatted(fullName, code, ttl.toMinutes());
		send(email, "Подтверждение email — ПТУ-Сошиал", text);
	}

	@Override
	public void sendTeacherInvite(String email, String fullName, String inviteLink, Duration ttl) {
		String text = """
				Здравствуйте, %s!

				Учебная часть приглашает вас в систему «ПТУ-Сошиал» как преподавателя.
				Перейдите по ссылке, чтобы установить пароль: %s
				Ссылка действует %d дней.
				""".formatted(fullName, inviteLink, ttl.toDays());
		send(email, "Приглашение преподавателя — ПТУ-Сошиал", text);
	}

	private void send(String email, String subject, String text) {
		SimpleMailMessage message = new SimpleMailMessage();
		message.setFrom(from);
		message.setTo(email);
		message.setSubject(subject);
		message.setText(text);
		try {
			mailSender.send(message);
		}
		catch (MailException ex) {
			log.error("Failed to send email to {}", email, ex);
			throw new ApiException(org.springframework.http.HttpStatus.BAD_GATEWAY,
					"Не удалось отправить письмо, попробуйте позже");
		}
	}
}
